import{HEROES,SKILLS,gearSupports}from'./expedition-data.mjs';
export const BARD_MOTION_RULE='携乐器吟游者用同一原创关节模型表现已记录的施放、效果组件、心理攻击、受击和倒下。同组一次施放的多位目标或多个组件只演一次拨弦，逐条诊断仅示意当前记录，不代表额外行动或额外支援；待生效组件不画已生效的余音。图形留在本人卡片内，不新增弹道、命中或移动。数值与目标仍显示原步快照，900毫秒是演出节奏而非战斗时间；暂停及减少动态收束到本步存活或倒下姿态。';
export function bardMotion(group,hero){
 if(!hero||HEROES.find(h=>h.id===hero.id)?.classId!=='bard'||!gearSupports(hero.gear,'lute')||!group?.events?.length)return null;
 const events=group.events,unit=events.at(-1).units.find(u=>u.id===hero.id);if(!unit)return null;const beats=[],effects=new Set(),attacks=new Set(),add=(e,pose,label)=>beats.push({eventId:e.id,pose,label});
 for(const e of events){const d=e.detail,own=e.actor===hero.id,recipient=e.targets.includes(hero.id),skill=SKILLS[d.skill];
  if(e.type==='cast'&&own&&(skill?.kind==='buff'||skill?.kind==='attack'&&skill.type==='mental'))add(e,'prepare','施放「'+skill.name+'」');
  if(e.type==='effect'&&own&&skill?.kind==='buff'&&!effects.has(d.cast??e.id)){effects.add(d.cast??e.id);add(e,d.active===false?'hold':'strum',d.active===false?'组件待生效':'已记录「'+skill.name+'」组件');}
  if(e.type==='attack'&&own&&d.attackType==='mental'&&!attacks.has(d.cast??e.id)){attacks.add(d.cast??e.id);add(e,'accent','实际心理攻击');}
  if(e.type==='defend'&&own&&d.skill==='dodge')add(e,'ready','闪避检定');
  if((e.type==='attack'||e.type==='harm')&&recipient){if(d.grade==='闪避')add(e,'evade','实际闪避');else if(d.actual>0)add(e,'hit','受击 −'+d.actual);else add(e,'steady','实扣0');}
  if(e.type==='down'&&recipient)add(e,'fallen','倒下');
 }
 return{id:hero.id,name:unit.name,settled:unit.hp<=0?'fallen':'idle',mode:beats.at(-1)?.pose||(unit.hp<=0?'fallen':'idle'),beats,sourceEvents:[...new Set(beats.map(b=>b.eventId))],label:beats.map(b=>b.label).join(' → ')||(unit.hp<=0?'已倒下':'待命'),rule:BARD_MOTION_RULE};
}
const idle={root:[0,0,0],torso:[0,0,0],head:[0,0,0],luteArm:[0,0,0],luteHand:[0,0,0],strumArm:[0,0,0],strumHand:[0,0,0],legL:[0,0,0],legR:[0,0,0],resonance:[0,0,0,0]},pose=x=>({...idle,...x});
export const BARD_POSES={idle,prepare:pose({torso:[0,0,-4],head:[0,0,-5],luteArm:[0,0,-3],luteHand:[0,0,-3],strumArm:[0,0,-18],strumHand:[0,0,-10],legR:[0,0,3]}),strum:pose({torso:[0,0,3],head:[0,0,2],luteArm:[0,0,-3],luteHand:[0,0,1],strumArm:[0,0,8],strumHand:[0,0,9],resonance:[0,0,0,.75]}),hold:pose({torso:[0,0,1],luteArm:[0,0,-3],strumArm:[0,0,3],strumHand:[0,0,3]}),accent:pose({torso:[0,0,6],head:[0,0,-4],luteArm:[0,0,-7],strumArm:[0,0,14],strumHand:[0,0,15],legL:[0,0,-4],resonance:[0,0,0,1]}),ready:pose({torso:[0,0,-4],luteArm:[0,0,7],strumArm:[0,0,-6]}),evade:pose({root:[-5,0,-11],torso:[0,0,-8],head:[0,0,4],luteArm:[0,0,7],strumArm:[0,0,-5],legL:[0,0,10],legR:[0,0,12]}),hit:pose({root:[-2,1,-6],torso:[0,0,-13],head:[0,0,-9],luteArm:[0,0,9],strumArm:[0,0,16],legL:[0,0,7]}),steady:pose({torso:[0,0,-3],luteArm:[0,0,5]}),fallen:pose({root:[39,-43,-74],torso:[0,0,-8],head:[0,0,-12],luteArm:[0,0,10],luteHand:[0,0,-8],strumArm:[0,0,20],legL:[0,0,-10],legR:[0,0,12]})};
const transform=([x,y,a])=>`translate(${x}px, ${y}px) rotate(${a}deg)`;
export function bardKeyframes(plan,{speed=1,reduced=false}={}){if(![.5,1,2,4].includes(speed))throw Error('动作播放速度无效');const settled=BARD_POSES[plan.settled],poses=[{offset:0,pose:plan.settled==='fallen'&&!plan.beats.length?settled:idle},...plan.beats.map((b,i)=>({offset:(i+1)/(plan.beats.length+2),pose:BARD_POSES[b.pose]})),{offset:1,pose:settled}];return{duration:900/speed,animated:!reduced&&plan.beats.length>0,parts:Object.fromEntries(Object.keys(idle).map(key=>[key,{settled:transform(settled[key]),opacity:settled[key][3]??1,frames:poses.map(p=>({offset:p.offset,transform:transform(p.pose[key]),opacity:p.pose[key][3]??1}))}]))};}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function bardFigure(plan){return `<svg class="bard-figure" viewBox="-24 -20 168 164" aria-hidden="true" focusable="false" data-bard-id="${esc(plan.id)}" data-bard-motion="${esc(plan.mode)}" data-motion-events="${esc(plan.sourceEvents.join(','))}"><ellipse class="bard-shadow" cx="60" cy="${plan.settled==='fallen'?115:119}" rx="30" ry="${plan.settled==='fallen'?3:5}"/><g data-bard-part="root"><path class="bard-cloak" d="M44 43Q31 70 34 105L82 105Q80 68 73 43Z"/><g data-bard-part="legL"><path class="bard-leg" d="M50 77L48 99L46 115H57L61 80Z"/><path class="bard-boot" d="M46 109H58L59 118H42Z"/></g><g data-bard-part="legR"><path class="bard-leg" d="M61 78L65 99L68 115H78L74 80Z"/><path class="bard-boot" d="M66 109H78L82 118H66Z"/></g><g data-bard-part="torso"><path class="bard-coat" d="M44 44Q59 37 74 44L74 78L47 80Z"/><path class="bard-trim" d="M49 44L57 55L66 43L68 71H51Z"/><path class="bard-sash" d="M46 73L74 70L75 78L47 82Z"/><g data-bard-part="head"><path class="bard-skin" d="M54 34L54 45L65 44L65 34Z"/><path class="bard-face" d="M49 23Q59 16 70 23L69 35L62 41L52 36Z"/><path class="bard-hair" d="M47 29Q43 13 59 15Q74 14 73 29L66 23L56 28L51 25L50 33Z"/><path class="bard-eye" d="M61 29H68"/><path class="bard-collar" d="M49 38L58 43L68 37L67 45H52Z"/></g><g data-bard-part="luteArm"><path class="bard-coat" d="M45 45L39 50L46 66L53 63Z"/><g data-bard-part="luteHand"><path class="bard-skin" d="M47 60L53 58L81 59L84 65L53 67Z"/><path class="bard-cuff" d="M76 58L84 57L87 65L78 68Z"/><ellipse class="bard-lute" cx="72" cy="83" rx="13" ry="17" transform="rotate(30 72 83)"/><path class="bard-wood" d="M75 71L91 48L96 51L80 76Z"/><path class="bard-peg" d="M89 45L96 46L99 51L94 56L89 53Z"/><path class="bard-strings" d="M67 88L92 50M70 90L94 52M72 91L95 53"/><ellipse class="bard-soundhole" cx="73" cy="81" rx="3.5" ry="4" transform="rotate(30 73 81)"/><path class="bard-bridge" d="M64 89L73 95"/><g data-bard-part="resonance"><path class="bard-note" d="M91 74Q100 81 92 89M96 69Q110 81 98 94"/></g></g></g><g data-bard-part="strumArm"><path class="bard-coat" d="M71 44L79 47L83 61L76 65L69 53Z"/><g data-bard-part="strumHand"><path class="bard-skin" d="M77 60L83 63L77 81L71 82L72 75Z"/><path class="bard-cuff" d="M70 76L78 78L77 85L69 84Z"/><path class="bard-skin" d="M69 82L76 83L74 89L68 87Z"/></g></g></g></g></svg><span class="bard-pose-label">本步：${esc(plan.beats.at(-1)?.label||(plan.settled==='fallen'?'已倒下':'吟游者'))}</span>`;}
export function animateBardFigures(root,plans,{speed=1,reduced=false}={}){const running=[];for(const plan of plans){const svg=[...root.querySelectorAll('[data-bard-id]')].find(n=>n.dataset.bardId===plan.id);if(!svg)continue;const k=bardKeyframes(plan,{speed,reduced});svg.dataset.motionDuration=String(k.duration);svg.dataset.motionAnimated=String(k.animated);for(const[key,part]of Object.entries(k.parts)){const n=svg.querySelector('[data-bard-part="'+key+'"]');n.style.transform=part.settled;n.style.opacity=part.opacity;if(k.animated&&typeof n.animate==='function')running.push(n.animate(part.frames,{duration:k.duration,easing:'linear',fill:'none'}));}}return{cancel(){for(const a of running)a.cancel();},count:running.length};}
